    fn new() -> Self { Self { buf: Buffer::empty(Rect::new(0,0,200,40)) } }
    fn render<F: FnOnce(&mut ratatui::Frame)>(&mut self, f: F) {
        let mut frame = ratatui::Frame { area: Rect::new(0,0,200,40), buffer: &mut self.buf, count: 0 };
        f(&mut frame);
    }
    fn lines(&mut self) -> Vec<String> {
        let mut out = vec![];
        for y in 0..10 {
            let mut s = String::new();
            for x in 0..200 {
                let c = self.buf[(x,y)].symbol();
                s.push_str(c);
            }
            let t = s.trim_end().to_string();
            if !t.is_empty() { out.push(t); }
        }
        out
    }
}
EOF
