    let hint = "Enter or <Ctrl-m>: confirm | Esc or <Ctrl-c>: Cancel | Tab: Change focused control | <Ctrl-Space> or <Ctrl-t>: Open tags";
    for w in 44..=100u16 {
        let backend = TestBackend::new(w, 20);
        let mut term = Terminal::new(backend).unwrap();
        term.draw(|f| {
            let area = f.area();
            let p = Paragraph::new(hint).wrap(Wrap{trim:true}).alignment(Alignment::Center);
            f.render_widget(p, area);
        }).unwrap();
        let b = term.backend();
        let lines: Vec<String> = (0..20u16).map(|y| {
            let mut s = String::new();
            for x in 0..w { s.push_str(b.buffer()[(x,y)].symbol()); }
