use ratatui::prelude::*;
use ratatui::widgets::*;
use ratatui::layout::Constraint;
fn runs<H: Fn(u16)->Rects>(name: &str, f: H, hs: &[u16]) {
    let mut out = vec![];
    for &h in hs {
        let rects = f(h);
        let m = &rects[1];
        out.push(format!("H={}: y={} h={}", h, m.y, m.height));
