use chrono::{DateTime, NaiveDate, TimeZone, Utc};
use serde::{Deserialize, Serialize};

pub const TRANSFER_VERSION: i32 = 100;

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Entry {
    pub id: u32,
    pub date: DateTime<Utc>,
    pub title: String,
    pub content: String,
    pub tags: Vec<String>,
    pub priority: Option<u32>,
}

impl Entry {
    pub fn new(id: u32, date: DateTime<Utc>, title: String, priority: Option<u32>) -> Self {
        Self { id, date, title, content: String::new(), tags: vec![], priority }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct TransferEntry {
    pub date: DateTime<Utc>,
    pub title: String,
    pub content: String,
    pub tags: Vec<String>,
    pub priority: Option<u32>,
}

impl From<&Entry> for TransferEntry {
    fn from(e: &Entry) -> Self {
        Self { date: e.date, title: e.title.clone(), content: e.content.clone(), tags: e.tags.clone(), priority: e.priority }
    }
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Transfer {
    pub version: i32,
    pub entries: Vec<TransferEntry>,
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum SortDirection { Ascending, Descending }

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq, Hash)]
pub enum SortCriteria { Date, Priority, Title }

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Sorter {
    pub criteria: Vec<SortCriteria>,
    pub order: SortDirection,
}

impl Sorter {
    pub fn default_sorter() -> Self {
        Self { criteria: vec![SortCriteria::Date, SortCriteria::Priority], order: SortDirection::Descending }
    }
}

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum MatchingLogic { All, Any }

/// returns today's date at midnight UTC
pub fn today_date() -> DateTime<Utc> {
    let now = Utc::now();
    let nd = now.date_naive();
    nd.and_hms_opt(0, 0, 0).unwrap().and_utc()
}

pub fn tomorrow_date() -> DateTime<Utc> { today_date() }

/// Format the date as DD-MM-YYYY (for the entry inputs)
pub fn format_date_input(d: &DateTime<Utc>) -> String {
    let nd = d.date_naive();
    format!("{:02}-{:02}-{:04}", nd.day(), nd.month(), nd.year())
}

/// Parse DD-MM-YYYY
pub fn parse_date_input(s: &str) -> Option<NaiveDate> {
    let parts: Vec<&str> = s.split('-').collect();
    if parts.len() != 3 { return None; }
    let d: u32 = parts[0].parse().ok()?;
    let m: u32 = parts[1].parse().ok()?;
    let y: i32 = parts[2].parse().ok()?;
    NaiveDate::from_ymd_opt(y, m, d)
}

/// Format used inside the journals list: DD,MM,YYYY
pub fn format_date_list(d: &DateTime<Utc>) -> String {
    let nd = d.date_naive();
    format!("{:02},{:02},{:04}", nd.day(), nd.month(), nd.year())
}
EOF
echo written"}

