{"command": "cd /workspace && cat > src/config.rs <<'EOF'
use serde::{Deserialize, Serialize};
use std::path::{Path, PathBuf};

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum BackendType { Json, Sqlite }

#[derive(Clone, Copy, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub enum DatumVisibility { #[serde(rename = "show")] Show, #[serde(rename = "hide")] Hide }

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct ExportSettings { pub show_confirmation: bool }

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct ExternalEditorSettings {
    pub auto_save: bool,
    pub temp_file_extension: String,
}

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct JsonBackendSettings { pub file_path: PathBuf }

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct SqliteBackendSettings { pub file_path: PathBuf }

#[derive(Clone, Debug, Serialize, Deserialize, PartialEq, Eq)]
pub struct Settings {
    pub backend_type: BackendType,
    pub scroll_per_page: u16,
    pub sync_os_clipboard: bool,
    pub history_limit: u16,
    pub colored_tags: bool,
    pub datum_visibility: DatumVisibility,
    pub app_state_dir: PathBuf,
    pub export: ExportSettings,
    pub external_editor: ExternalEditorSettings,
    pub json_backend: JsonBackendSettings,
    pub sqlite_backend: SqliteBackendSettings,
}

fn xdg_home(sub: &str) -> PathBuf {
    let env = std::env::var_os(format!("XDG_{}_HOME", sub.to_uppercase()));
    let base = match env {
        Some(v) if !v.is_empty() && Path::new(&v).is_absolute() => PathBuf::from(v),
        _ => {
            let home = std::env::var_os("HOME").map(PathBuf::from).unwrap_or_default();
            home.join(match sub { "config" => ".config", "cache" => ".cache", _ => ".local/state" })
        }
    };
    base
}

impl Settings {
    pub fn config_dir() -> PathBuf { xdg_home("config").join("tui-journal") }
    pub fn default_log_file() -> PathBuf { xdg_home("cache").join("tui-journal").join("tui-journal.log") }
    pub fn default_state_dir() -> PathBuf { xdg_home("state").join("tui-journal") }

    pub fn default_json_path() -> PathBuf {
        std::env::var_os("HOME").map(|h| PathBuf::from(h).join("tui-journal").join("entries.json"))
            .unwrap_or_else(|| PathBuf::from("entries.json"))
    }
    pub fn default_sqlite_path() -> PathBuf {
        std::env::var_os("HOME").map(|h| PathBuf::from(h).join("tui-journal").join("entries.db"))
            .unwrap_or_else(|| PathBuf::from("entries.db"))
    }

    pub fn default() -> Self {
        Self {
            backend_type: BackendType::Sqlite,
            scroll_per_page: 5,
            sync_os_clipboard: false,
            history_limit: 10,
            colored_tags: true,
            datum_visibility: DatumVisibility::Show,
            app_state_dir: Self::default_state_dir(),
            export: ExportSettings { show_confirmation: true },
            external_editor: ExternalEditorSettings { auto_save: false, temp_file_extension: "txt".into() },
            json_backend: JsonBackendSettings { file_path: Self::default_json_path() },
            sqlite_backend: SqliteBackendSettings { file_path: Self::default_sqlite_path() },
        }
    }

    pub fn config_file_path(dir: &Path) -> PathBuf { dir.join("config.toml") }

    pub fn read(dir: &Path) -> anyhow::Result<Self> {
        let path = Self::config_file_path(dir);
        let content = std::fs::read_to_string(&path)
            .map_err(|e| anyhow::anyhow!("Failed to read configuration file. Error infos: {}", e))?;
        let s: Settings = toml::from_str(&content)
            .map_err(|e| anyhow::anyhow!("Failed to read configuration file. Error infos: {}", crate_toml_error(&e)))?;
        Ok(s)
    }

    pub fn to_toml_string(&self) -> String {
        crate_toml_string(self)
    }
}

pub fn crate_toml_string<T: serde::Serialize>(v: &T) -> String {
    toml::to_string(v).unwrap_or_default()
}

fn crate_toml_error(e: &toml::de::Error) -> String {
    e.to_string()
}
EOF
echo ok"}

