#[derive(Clone, Copy, Debug, Default, PartialEq, Eq)]
pub struct ThemeStyle {
    pub fg: Option<Color>,
    pub bg: Option<Color>,
    pub modifiers: Option<Modifier>,
    pub underline_color: Option<Color>,
}

impl ThemeStyle {
    pub const fn new() -> Self { Self { fg: None, bg: None, modifiers: None, underline_color: None } }
    pub const fn fg(c: Color) -> Self { Self { fg: Some(c), bg: None, modifiers: None, underline_color: None } }
