        if let Some(uc) = self.underline_color { s = s.underline_color(uc); }
        s
    }
}

fn color_name(c: Color) -> Option<String> {
    Some(match c {
        Color::Reset => "Reset".into(),
        Color::Black => "Black".into(),
        Color::Red => "Red".into(),
        Color::Green => "Green".into(),
        Color::Yellow => "Yellow".into(),
        Color::Blue => "Blue".into(),
        Color::Magenta => "Magenta".into(),
        Color::Cyan => "Cyan".into(),
        Color::Gray => "Gray".into(),
        Color::DarkGray => "DarkGray".into(),
        Color::LightRed => "LightRed".into(),
        Color::LightGreen => "LightGreen".into(),
        Color::LightYellow => "LightYellow".into(),
        Color::LightBlue => "LightBlue".into(),
        Color::LightMagenta => "LightMagenta".into(),
        Color::LightCyan => "LightCyan".into(),
        Color::White => "White".into(),
        Color::Rgb(r, g, b) => return Some(format!("#{:02X}{:02X}{:02X}", r, g, b)),
        Color::Indexed(i) => return Some(format!("Indexed({})", i)),
        _ => return None,
    })
}

fn parse_color(s: &str) -> Option<Color> {
    let t = s.trim();
    if let Some(hex) = t.strip_prefix('#') {
        if hex.len() == 6 {
            let r = u8::from_str_radix(&hex[0..2], 16).ok()?;
            let g = u8::from_str_radix(&hex[2..4], 16).ok()?;
            let b = u8::from_str_radix(&hex[4..6], 16).ok()?;
            return Some(Color::Rgb(r, g, b));
        }
        return None;
    }
    if let Some(rest) = t.strip_prefix("Indexed(") {
        let rest = rest.trim_end_matches(')');
        if let Ok(i) = rest.parse::<u8>() { return Some(Color::Indexed(i)); }
        return None;
    }
    Some(match t {
        "Reset" => Color::Reset,
        "Black" => Color::Black,
        "Red" => Color::Red,
        "Green" => Color::Green,
        "Yellow" => Color::Yellow,
        "Blue" => Color::Blue,
        "Magenta" => Color::Magenta,
        "Cyan" => Color::Cyan,
        "Gray" | "Grey" => Color::Gray,
        "DarkGray" | "DarkGrey" => Color::DarkGray,
        "LightRed" => Color::LightRed,
        "LightGreen" => Color::LightGreen,
        "LightYellow" => Color::LightYellow,
        "LightBlue" => Color::LightBlue,
        "LightMagenta" => Color::LightMagenta,
        "LightCyan" => Color::LightCyan,
        "White" => Color::White,
        _ => return None,
    })
}

fn modifiers_str(m: Modifier) -> String {
    let mut parts: Vec<&str> = vec![];
    for (flag, name) in [
        (Modifier::BOLD, "BOLD"),
        (Modifier::DIM, "DIM"),
        (Modifier::ITALIC, "ITALIC"),
        (Modifier::UNDERLINED, "UNDERLINED"),
        (Modifier::SLOW_BLINK, "SLOW_BLINK"),
        (Modifier::RAPID_BLINK, "RAPID_BLINK"),
        (Modifier::REVERSED, "REVERSED"),
        (Modifier::HIDDEN, "HIDDEN"),
        (Modifier::CROSSED_OUT, "CROSSED_OUT"),
    ] {
        if m.contains(flag) { parts.push(name); }
    }
    parts.join(" | ")
}

fn parse_modifiers(s: &str) -> Option<Modifier> {
    let t = s.trim();
    if t.is_empty() { return Some(Modifier::empty()); }
    let mut m = Modifier::empty();
    for p in t.split('|') {
        m |= match p.trim() {
            "BOLD" => Modifier::BOLD,
            "DIM" => Modifier::DIM,
            "ITALIC" => Modifier::ITALIC,
            "UNDERLINED" => Modifier::UNDERLINED,
            "SLOW_BLINK" => Modifier::SLOW_BLINK,
            "RAPID_BLINK" => Modifier::RAPID_BLINK,
            "REVERSED" => Modifier::REVERSED,
            "HIDDEN" => Modifier::HIDDEN,
            "CROSSED_OUT" => Modifier::CROSSED_OUT,
            "" => Modifier::empty(),
            _ => return None,
        };
    }
    Some(m)
}

impl Serialize for ThemeStyle {
    fn serialize<S: serde::Serializer>(&self, serializer: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeMap;
        let mut map = serializer.serialize_map(None)?;
        if let Some(fg) = self.fg { map.serialize_entry("fg", &color_name(fg))?; }
        if let Some(bg) = self.bg { map.serialize_entry("bg", &color_name(bg))?; }
        map.serialize_entry("modifiers", &modifiers_str(self.modifiers.unwrap_or_default()))?;
        if let Some(uc) = self.underline_color { map.serialize_entry("underline_color", &color_name(uc))?; }
        map.end()
    }
}

impl<'de> Deserialize<'de> for ThemeStyle {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
        struct Raw {
            fg: Option<String>,
            bg: Option<String>,
            modifiers: Option<String>,
            underline_color: Option<String>,
        }
        let raw = Raw::deserialize(d)?;
        Ok(Self {
            fg: raw.fg.as_deref().and_then(parse_color),
            bg: raw.bg.as_deref().and_then(parse_color),
            modifiers: raw.modifiers.as_deref().and_then(parse_modifiers),
            underline_color: raw.underline_color.as_deref().and_then(parse_color),
        })
    }
}

fn msg_color_name(c: Color) -> String { color_name(c).unwrap_or_default() }

fn parse_msg_color(s: &str) -> Option<Color> { parse_color(s) }

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct MsgBoxColors { pub error: Color, pub warning: Color, pub info: Color, pub question: Color }

impl Serialize for MsgBoxColors {
    fn serialize<S: serde::Serializer>(&self, s: S) -> Result<S::Ok, S::Error> {
        use serde::ser::SerializeMap;
        let mut m = s.serialize_map(None)?;
        m.serialize_entry("error", &msg_color_name(self.error))?;
        m.serialize_entry("warning", &msg_color_name(self.warning))?;
        m.serialize_entry("info", &msg_color_name(self.info))?;
        m.serialize_entry("question", &msg_color_name(self.question))?;
        m.end()
    }
}

impl<'de> Deserialize<'de> for MsgBoxColors {
    fn deserialize<D: serde::Deserializer<'de>>(d: D) -> Result<Self, D::Error> {
        #[derive(Deserialize)]
