const STATIC: *const c_void = std::ptr::null();

pub struct Conn { db: *mut sqlite3 }

unsafe impl Send for Conn {}

impl Conn {
    pub fn open(path: &Path) -> Result<Self, String> {
        let cpath = CString::new(path.to_string_lossy().as_bytes()).unwrap();
        let mut db: *mut sqlite3 = std::ptr::null_mut();
        unsafe {
            let rc = sqlite3_open_v2(cpath.as_ptr(), &mut db, SQLITE_OPEN_READWRITE_CREATE, std::ptr::null());
            if rc != SQLITE_OK {
                let msg = if !db.is_null() { errmsg(db) } else { "unable to open database file".to_string() };
                if !db.is_null() { sqlite3_close_v2(db); }
                return Err(msg);
            }
        }
        Ok(Self { db })
    }

    pub fn errmsg(&self) -> String { unsafe { errmsg(self.db) } }

    pub fn exec(&self, sql: &str) -> Result<(), String> {
        let c = CString::new(sql).unwrap();
        unsafe {
            let mut stmt: *mut sqlite3_stmt = std::ptr::null_mut();
            let rc = sqlite3_prepare_v2(self.db, c.as_ptr(), -1, &mut stmt, std::ptr::null_mut());
            if rc != SQLITE_OK { return Err(self.errmsg()); }
            loop {
                let rc = sqlite3_step(stmt);
                if rc == SQLITE_DONE { break; }
                if rc == SQLITE_ROW { continue; }
                sqlite3_finalize(stmt);
                return Err(self.errmsg());
            }
            sqlite3_finalize(stmt);
        }
        Ok(())
    }

    pub fn last_insert_rowid(&self) -> i64 { unsafe { sqlite3_last_insert_rowid(self.db) } }
}

unsafe fn errmsg(db: *mut sqlite3) -> String {
    let p = sqlite3_errmsg(db);
    if p.is_null() { String::new() } else { CStr::from_ptr(p).to_string_lossy().into_owned() }
}

pub struct Stmt<'a> { stmt: *mut sqlite3_stmt, _db: &'a Conn }

impl<'a> Stmt<'a> {
    pub fn prepare(db: &'a Conn, sql: &str) -> Result<Self, String> {
        let c = CString::new(sql).unwrap();
        unsafe {
            let mut stmt: *mut sqlite3_stmt = std::ptr::null_mut();
            let rc = sqlite3_prepare_v2(db.db, c.as_ptr(), -1, &mut stmt, std::ptr::null_mut());
            if rc != SQLITE_OK { return Err(db.errmsg()); }
            Ok(Self { stmt, _db: db })
        }
    }
    pub fn bind_text(&mut self, idx: usize, v: &str) -> Result<(), String> {
        unsafe {
            let c = CString::new(v.replace('\0', "")).unwrap();
            let rc = sqlite3_bind_text(self.stmt, idx as c_int, c.as_ptr(), c.as_bytes().len() as c_int, STATIC);
            if rc != SQLITE_OK { return Err(self._db.errmsg()); }
        }
        Ok(())
    }
    pub fn bind_i64(&mut self, idx: usize, v: i64) -> Result<(), String> {
        unsafe { if sqlite3_bind_int64(self.stmt, idx as c_int, v) != SQLITE_OK { return Err(self._db.errmsg()); } }
        Ok(())
    }
    pub fn bind_null(&mut self, idx: usize) -> Result<(), String> {
        unsafe { if sqlite3_bind_null(self.stmt, idx as c_int) != SQLITE_OK { return Err(self._db.errmsg()); } }
        Ok(())
    }
    pub fn step(&mut self) -> Result<bool, String> {
        unsafe {
            match sqlite3_step(self.stmt) {
                SQLITE_ROW => Ok(true),
                SQLITE_DONE => Ok(false),
                _ => Err(self._db.errmsg()),
            }
        }
    }
    pub fn text(&mut self, idx: usize) -> String {
        unsafe {
            let p = sqlite3_column_text(self.stmt, idx as c_int);
            if p.is_null() { String::new() } else {
                let n = sqlite3_column_bytes(self.stmt, idx as c_int);
                std::slice::from_raw_parts(p, n.max(0) as usize).iter().map(|&b| b as char).collect::<String>()
            }
        }
    }
    pub fn text_utf8(&mut self, idx: usize) -> String {
        unsafe {
            let p = sqlite3_column_text(self.stmt, idx as c_int);
            if p.is_null() { String::new() } else {
                let n = sqlite3_column_bytes(self.stmt, idx as c_int);
                String::from_utf8_lossy(std::slice::from_raw_parts(p, n.max(0) as usize)).into_owned()
            }
        }
    }
    pub fn is_null(&mut self, idx: usize) -> bool {
        unsafe { sqlite3_column_type(self.stmt, idx as c_int) == 5 }
    }
    pub fn i64(&mut self, idx: usize) -> i64 { unsafe { sqlite3_column_int64(self.stmt, idx as c_int) } }
    pub fn cols(&self) -> usize { unsafe { sqlite3_column_count(self.stmt) as usize } }
}

impl<'a> Drop for Stmt<'a> {
    fn drop(&mut self) { unsafe { sqlite3_finalize(self.stmt); } }
}

impl Drop for Conn {
    fn drop(&mut self) { unsafe { sqlite3_close_v2(self.db); } }
}

pub fn libversion() -> String {
    unsafe {
        let p = sqlite3_libversion();
        if p.is_null() { String::new() } else { CStr::from_ptr(p).to_string_lossy().into_owned() }
    }
}

