pub fn ensure_migrated(conn: &Conn) -> Result<(), String> {
    conn.exec("CREATE TABLE IF NOT EXISTS _sqlx_migrations (\n    version BIGINT PRIMARY KEY,\n    description TEXT NOT NULL,\n    installed_on TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,\n    success BOOLEAN NOT NULL,\n    checksum BLOB NOT NULL,\n    execution_time BIGINT NOT NULL\n)")?;
    for (version, desc, _sql, checksum) in MIGRATIONS {
        let applied = {
            let mut st = Stmt::prepare(conn, "SELECT COUNT(*) FROM _sqlx_migrations WHERE version = ?1")?;
            st.bind_i64(1, *version)?;
            let mut cnt = 0i64;
            if st.step()? { cnt = st.i64(0); }
            cnt > 0
        };
        if applied { continue; }
        conn.exec(_sql)?;
        let hex: String = checksum.iter().map(|b| format!("{:02x}", b)).collect();
        let q = format!(
            "INSERT INTO _sqlx_migrations (version, description, installed_on, success, checksum, execution_time) VALUES ({}, '{}', CURRENT_TIMESTAMP, 1, X'{}', 0)",
            version, desc, hex
        );
        conn.exec(&q)?;
    }
    Ok(())
}
