pub const SQLITE_OK: c_int = 0;
pub const SQLITE_ROW: c_int = 100;
pub const SQLITE_DONE: c_int = 101;
pub const SQLITE_OPEN_READWRITE_CREATE: c_int = 0x00000006;

#[repr(C)]
pub struct sqlite3 { _private: [u8; 0] }
#[repr(C)]
pub struct sqlite3_stmt { _private: [u8; 0] }

extern "C" {
    fn sqlite3_open_v2(filename: *const c_char, db: *mut *mut sqlite3, flags: c_int, vfs: *const c_char) -> c_int;
    fn sqlite3_close_v2(db: *mut sqlite3) -> c_int;
