use crate::model::{Entry, Transfer, TransferEntry};
use std::path::Path;

pub trait Backend {
    fn load(&self) -> anyhow::Result<Vec<Entry>>;
    fn save(&self, entries: &[Entry]) -> anyhow::Result<()>;
}

pub struct JsonBackend { pub path: std::path::PathBuf }

impl Backend for JsonBackend {
    fn load(&self) -> anyhow::Result<Vec<Entry>> {
        if !self.path.exists() { return Ok(vec![]); }
        let content = std::fs::read_to_string(&self.path)?;
        let v: Vec<Entry> = serde_json::from_str(&content)?;
        Ok(v)
    }
    fn save(&self, entries: &[Entry]) -> anyhow::Result<()> {
        let s = serde_json::to_string(entries)?;
        std::fs::write(&self.path, s)?;
        Ok(())
    }
}

pub struct SqliteBackend { pub path: std::path::PathBuf }

impl Backend for SqliteBackend {
    fn load(&self) -> anyhow::Result<Vec<Entry>> {
        let conn = crate::sqlite::Conn::open(&self.path).map_err(|e| anyhow::anyhow!("{}", e))?;
        crate::sqlite::ensure_migrated(&conn).map_err(|e| anyhow::anyhow!("{}", e))?;
        let mut out: Vec<Entry> = vec![];
        let mut st = crate::sqlite::Stmt::prepare(&conn,
            "SELECT id, title, date, content, priority FROM entries").map_err(|e| anyhow::anyhow!("{}", e))?;
        while st.step().map_err(|e| anyhow::anyhow!("{}", e))? {
            let id = st.i64(0) as u32;
            let title = st.text_utf8(1);
            let date_s = st.text_utf8(2);
            let content = st.text_utf8(3);
            let prio = if st.is_null(4) { None } else { Some(st.i64(4) as u32) };
            let date = crate::model::parse_db_date(&date_s)
                .ok_or_else(|| anyhow::anyhow!("invalid date in database: {}", date_s))?;
            out.push(Entry { id, date, title, content, tags: vec![], priority: prio });
        }
        let mut ts = crate::sqlite::Stmt::prepare(&conn, "SELECT entry_id, tag FROM tags").map_err(|e| anyhow::anyhow!("{}", e))?;
        while ts.step().map_err(|e| anyhow::anyhow!("{}", e))? {
            let id = ts.i64(0) as u32;
            let tag = ts.text_utf8(1);
            if let Some(e) = out.iter_mut().find(|e| e.id == id) { e.tags.push(tag); }
        }
        Ok(out)
    }
    fn save(&self, entries: &[Entry]) -> anyhow::Result<()> {
        let conn = crate::sqlite::Conn::open(&self.path).map_err(|e| anyhow::anyhow!("{}", e))?;
        crate::sqlite::ensure_migrated(&conn).map_err(|e| anyhow::anyhow!("{}", e))?;
        conn.exec("DELETE FROM tags").map_err(|e| anyhow::anyhow!("{}", e))?;
        conn.exec("DELETE FROM entries").map_err(|e| anyhow::anyhow!("{}", e))?;
        for e in entries {
            let ds = crate::model::to_db_date(&e.date);
            let prio: Option<i64> = e.priority.map(|p| p as i64);
            let sql = match prio {
                Some(p) => format!("INSERT INTO entries (id, title, date, content, priority) VALUES ({}, '{}', '{}', '{}', {})",
                    e.id, escape(&e.title), ds, escape(&e.content), p),
                None => format!("INSERT INTO entries (id, title, date, content, priority) VALUES ({}, '{}', '{}', '{}', NULL)",
                    e.id, escape(&e.title), ds, escape(&e.content)),
            };
            conn.exec(&sql).map_err(|err| anyhow::anyhow!("{}", err))?;
            for t in &e.tags {
                let q = format!("INSERT INTO tags (entry_id, tag) VALUES ({}, '{}')", e.id, escape(t));
                conn.exec(&q).map_err(|err| anyhow::anyhow!("{}", err))?;
            }
        }
        Ok(())
    }
}

fn escape(s: &str) -> String { s.replace('\'', "''") }

pub fn make_backend(kind: crate::config::BackendType, settings: &crate::config::Settings) -> Box<dyn Backend> {
    match kind {
        crate::config::BackendType::Json => Box::new(JsonBackend { path: settings.json_backend.file_path.clone() }),
        crate::config::BackendType::Sqlite => Box::new(SqliteBackend { path: settings.sqlite_backend.file_path.clone() }),
    }
}

pub fn transfer_to_entries(t: &Transfer) -> Vec<Entry> {
    t.entries.iter().enumerate().map(|(i, te)| Entry {
        id: i as u32,
        date: te.date,
        title: te.title.clone(),
        content: te.content.clone(),
        tags: te.tags.clone(),
        priority: te.priority,
    }).collect()
}

pub fn read_transfer(path: &Path) -> anyhow::Result<Transfer> {
    let content = std::fs::read_to_string(path)?;
    Ok(serde_json::from_str(&content)?)
}

pub fn write_transfer(path: &Path, entries: &[Entry]) -> anyhow::Result<()> {
    let t = Transfer {
        version: crate::model::TRANSFER_VERSION,
        entries: entries.iter().map(TransferEntry::from).collect(),
    };
    let s = serde_json::to_string_pretty(&t)?;
    std::fs::write(path, s)?;
    Ok(())
}
