use crate::config::{BackendType, Settings};
use std::path::PathBuf;

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum BackendArg { Json, Sqlite }

fn build_cli() -> clap::Command {
    let config_dir = Settings::config_dir();
    let log_file = Settings::default_log_file();
    let conf_help = format!(
        "Specifies the path for the configuration directory.\nConfiguration files is considered as root for themes file too.\nIt still accepts the path for configuration file for backward compatibility.\n(default path: {})",
        config_dir.display()
    );
    let log_help = format!("Specifies a file to use for logging\n(default file: {})", log_file.display());
    clap::Command::new("tui-journal")
        .version(crate::VERSION)
        .about("Tui app allows writing and managing journals/notes from within the terminal With different local back-ends")
        .arg(clap::Arg::new("json_file_path").short('j').long("json-file-path")
            .value_name("FILE PATH").help("Sets the entries Json file path and starts using it"))
        .arg(clap::Arg::new("sqlite_file_path").short('s').long("sqlite-file-path")
            .value_name("FILE PATH").help("Sets the entries sqlite file path and starts using it"))
        .arg(clap::Arg::new("backend_type").short('b').long("backend-type")
            .value_name("BACKEND_TYPE").help("Sets the backend type and starts using it")
            .value_parser(clap::builder::PossibleValuesParser::new(["json", "sqlite"])))
        .arg(clap::Arg::new("config").short('c').long("config")
            .value_name("DIR PATH").help(&conf_help).long_help(&conf_help))
        .arg(clap::Arg::new("verbose").short('v').long("verbose")
            .help("Increases logging verbosity each use for up to 3 times")
            .action(clap::ArgAction::Count))
        .arg(clap::Arg::new("log").short('l').long("log")
            .value_name("FILE PATH").help(&log_help).long_help(&log_help))
        .subcommand(clap::Command::new("print-config").about("Print the current settings including the paths for the back-end files").alias("pc"))
        .subcommand(clap::Command::new("import-journals").about("Import journals from the given transfer JSON file to the current back-end file").alias("imj")
            .arg(clap::Arg::new("path").short('p').long("path").value_name("FILE PATH")
                .help("Path of the JSON file to import from").required(true)))
        .subcommand(clap::Command::new("assign-priority").about("Assign priority for all the entries with empty priority field").alias("ap")
            .arg(clap::Arg::new("priority").value_name("PRIORITY").value_parser(clap::value_parser!(u32))
                .help("Priority value (Positive number)").required(true)))
        .subcommand(clap::Command::new("theme").about("Provides commands regarding changing themes and styles of the app").alias("style")
            .subcommand(clap::Command::new("print-path").about("Prints the path to the user themes file").alias("path"))
            .subcommand(clap::Command::new("print-default").about("Dumps the styles with the default values to be used as a reference and base for user custom themes").alias("default"))
            .subcommand(clap::Command::new("write-defaults").about("Creates user custom themes file if doesn't exist then writes the default styles to it").alias("write")))
}

fn main() {
    let cmd = build_cli();
    let matches = cmd.get_matches();
    let code = run(&matches);
    std::process::exit(code);
}

fn run(m: &clap::ArgMatches) -> i32 {
    let verbose = m.get_count("verbose");
    let log_path: Option<PathBuf> = m.get_one::<String>("log").map(PathBuf::from);
    crate::logging::init(verbose, log_path);

    // config directory
    let config_dir: PathBuf = match m.get_one::<String>("config") {
        Some(p) => {
            let pb = PathBuf::from(p);
            if !pb.exists() {
                eprintln!("Error: Provided custom directory doesn't exit. Path: {}", pb.display());
                return 1;
            }
            pb
        }
        None => Settings::config_dir(),
    };

    let mut settings = match Settings::read(&config_dir) {
        Ok(s) => s,
        Err(e) => { eprintln!("Error: {}", e); return 1; }
    };

    let json_path: Option<PathBuf> = m.get_one::<String>("json_file_path").map(PathBuf::from);
    let sqlite_path: Option<PathBuf> = m.get_one::<String>("sqlite_file_path").map(PathBuf::from);
    let backend_arg: Option<BackendArg> = m.get_one::<String>("backend_type").map(|s| {
        if *s == "json" { BackendArg::Json } else { BackendArg::Sqlite }
    });

    if let Some(p) = json_path.as_ref() { settings.json_backend.file_path = p.clone(); }
    if let Some(p) = sqlite_path.as_ref() { settings.sqlite_backend.file_path = p.clone(); }
    let backend = match backend_arg {
        Some(BackendArg::Json) => BackendType::Json,
        Some(BackendArg::Sqlite) => BackendType::Sqlite,
        None => if sqlite_path.is_some() { BackendType::Sqlite }
                else if json_path.is_some() { BackendType::Json }
                else { settings.backend_type },
    };
    settings.backend_type = backend;

    match m.subcommand() {
        Some(("print-config", _)) => {
            println!("{}", settings.to_toml_string());
            0
        }
        Some(("theme", sm)) => {
            match sm.subcommand() {
                Some(("print-path", _)) => {
                    println!("{}", config_dir.join("themes.toml").display());
                    0
                }
                Some(("print-default", _)) => {
                    println!("{}", crate::theme::DEFAULT_THEMES_TOML);
                    0
                }
                Some(("write-defaults", _)) => {
                    let path = config_dir.join("themes.toml");
                    if path.exists() {
                        eprintln!("Error: Themes file already exists. Path: {}", path.display());
                        1
                    } else {
                        match std::fs::write(&path, crate::theme::DEFAULT_THEMES_TOML) {
                            Ok(_) => { println!("Default themes have been written to {}", path.display()); 0 }
                            Err(e) => {
                                eprintln!("Error: Error while writing default themes to file\n\nCaused by:\n    {}", e);
                                1
                            }
                        }
                    }
                }
                _ => { let _ = sm; 0 }
            }
        }
        Some(("import-journals", sm)) => {
            let path = PathBuf::from(sm.get_one::<String>("path").unwrap());
            crate::cli_ops::run_import(&settings, backend, &path);
            0
        }
        Some(("assign-priority", sm)) => {
            let prio: u32 = *sm.get_one::<u32>("priority").unwrap();
            crate::cli_ops::run_assign_priority(&settings, backend, prio);
            0
        }
        _ => {
            // start the TUI
            match crate::ui::run(&settings, backend, &config_dir) {
                Ok(()) => 0,
                Err(e) => {
                    eprint!("Error: {}", crate::ui::format_error_chain(&*e));
                    1
                }
            }
        }
    }
}
