use crate::config::{BackendType, Settings};

pub fn run_import(settings: &Settings, backend: BackendType, path: &std::path::Path) {
    let entries = match crate::backend::make_backend(backend, settings).load() {
        Ok(e) => e,
        Err(e) => { eprintln!("Error: {}", crate::ui::format_error_chain(&*e)); std::process::exit(1); }
    };
    let transfer = match crate::backend::read_transfer(path) {
        Ok(t) => t,
        Err(e) => { eprintln!("Error: {}", crate::ui::format_error_chain(&*e)); std::process::exit(1); }
    };
    crate::ui::run_with_msg(settings, backend, entries, "Importing journals...", move |entries| {
        let new_entries = crate::backend::transfer_to_entries(&transfer);
        let mut max_id = entries.iter().map(|e| e.id).max().unwrap_or(0);
        let mut out = entries.clone();
        for e in new_entries {
            max_id += 1;
            let mut ne = e; ne.id = max_id;
            out.push(ne);
        }
        out
    });
}

pub fn run_assign_priority(settings: &Settings, backend: BackendType, priority: u32) {
    crate::ui::run_with_msg(settings, backend, vec![], "Assigning Priority to Journals...", move |entries| {
        let mut out = entries.clone();
        for e in out.iter_mut() {
            if e.priority.is_none() { e.priority = Some(priority); }
        }
        out
    });
}
EOF
