use std::fs::OpenOptions;
use std::io::Write;
use std::sync::Mutex;

pub enum Level { Warn, Info, Debug, Trace }

pub struct Logger {
    file: Option<std::fs::File>,
    level: Level,
}

static LOGGER: Mutex<Option<Logger>> = Mutex::new(None);

pub fn init(verbosity: u8, path: Option<std::path::PathBuf>) {
    let level = match verbosity {
        0 => Level::Warn,
        1 => Level::Info,
        2 => Level::Debug,
        _ => Level::Trace,
    };
    let p = path.unwrap_or_else(crate::config::Settings::default_log_file);
    if let Some(parent) = std::path::Path::new(&p).parent() {
        if !parent.as_os_str().is_empty() { let _ = std::fs::create_dir_all(parent); }
    }
    let file = OpenOptions::new().create(true).append(true).open(&p).ok();
    let mut g = LOGGER.lock().unwrap();
    *g = Some(Logger { file, level });
}

fn write_line(line: &str) {
    let mut g = LOGGER.lock().unwrap();
    if let Some(l) = g.as_mut() {
        if let Some(f) = l.file.as_mut() {
            let _ = f.write_all(line.as_bytes());
            let _ = f.write_all(b"\n");
            let _ = f.flush();
        }
    }
}

pub fn trace_init(level: &str) {
    let now = chrono::Local::now();
    let line = format!("{} [{}] (1) tjournal::logging: [src/logging.rs:38] Log initialized with level: {}",
        now.format("%H:%M:%S"), level, level);
    write_line(&line);
}
EOF
echo ok"}

