        let list: Vec<usize> = (0..self.entries.len()).collect();
        if !self.filter_active {
            self.filtered = list;
        } else {
            self.filtered = list.into_iter().filter(|i| self.matches(&self.entries[*i])).collect();
        }
        if self.filtered.is_empty() { self.selected = 0; }
        else if self.selected >= self.filtered.len() { self.selected = self.filtered.len() - 1; }
    }

