            match f.logic {
                MatchingLogic::All => checks.push(f.tags.iter().all(|t| e.tags.contains(t))),
                MatchingLogic::Any => checks.push(f.tags.iter().any(|t| e.tags.contains(t))),
            }
        }
        if checks.is_empty() { return true; }
        match f.logic { MatchingLogic::All => checks.iter().all(|b| *b), MatchingLogic::Any => checks.iter().any(|b| *b) }
    }

