        let mut idx: Vec<usize> = self.filtered.clone();
        let dir = self.sorter.order;
        for c in self.sorter.criteria.iter().rev() {
            match c {
                SortCriteria::Date => idx.sort_by(|a, b| self.entries[*a].date.cmp(&self.entries[*b].date)),
                SortCriteria::Priority => idx.sort_by(|a, b| match (self.entries[*a].priority, self.entries[*b].priority) {
                    (Some(x), Some(y)) => x.cmp(&y),
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, None) => std::cmp::Ordering::Equal,
                }),
                SortCriteria::Title => idx.sort_by(|a, b| self.entries[*a].title.cmp(&self.entries[*b].title)),
            }
            if dir == SortDirection::Descending { idx.reverse(); }
        }
        idx
    }

    fn current(&self) -> Option<&Entry> {
        let list = self.sorted();
        list.get(self.selected).map(|i| &self.entries[*i])
    }
    fn current_id(&self) -> Option<u32> { self.current().map(|e| e.id) }

    fn save(&self) -> anyhow::Result<()> {
        self.backend.save(&self.entries)
    }
}

fn all_criteria_except(applied: &[SortCriteria]) -> Vec<SortCriteria> {
    let all = [SortCriteria::Date, SortCriteria::Priority, SortCriteria::Title];
    all.into_iter().filter(|c| !applied.contains(c)).collect()
}

fn build_tag_colors(entries: &[Entry]) -> (Vec<(Option<Color>, Option<Color>)>, std::collections::HashMap<String, usize>) {
    let palette: [(Option<Color>, Option<Color>); 9] = [
        (Some(Color::Black), Some(Color::LightCyan)),
        (Some(Color::Black), Some(Color::LightRed)),
        (Some(Color::Black), Some(Color::LightGreen)),
        (None, Some(Color::DarkGray)),
        (Some(Color::Black), Some(Color::LightYellow)),
        (None, Some(Color::Red)),
        (Some(Color::Yellow), Some(Color::Blue)),
        (Some(Color::Red), Some(Color::Cyan)),
        (Some(Color::Black), Some(Color::LightMagenta)),
    ];
    let mut map = std::collections::HashMap::new();
    let mut idx = 0usize;
    for e in entries {
        for t in &e.tags {
            if !map.contains_key(t) { map.insert(t.clone(), idx); idx += 1; }
        }
    }
    (palette.to_vec(), map)
}
