    fn delete(&mut self) { if self.cursor < self.text.len() { self.text.remove(self.cursor); } }
    fn left(&mut self) { if self.cursor > 0 { self.cursor -= 1; } }
    fn right(&mut self) { if self.cursor < self.text.len() { self.cursor += 1; } }
    fn home(&mut self) { self.cursor = 0; }
    fn end(&mut self) { self.cursor = self.text.len(); }
