            selected: 0,
            multi_select: false,
            selected_set: Default::default(),
            focus: Focus::Journals,
            editor_mode: EditorMode::Normal,
            editor_dirty: false,
            popup: WhichPopup::None,
            dlg: DialogState { title: Input::new(""), date: Input::new(&model::format_date_input(&model::today_date())), priority: Input::new(""), tags: Input::new(""), focus: 0, valid_title: true, valid_date: true, valid_priority: true, valid_tags: true, editing: None },
            filter_popup: FilterState { logic: MatchingLogic::All, title: Input::new(""), content: Input::new(""), priority: Input::new(""), tags: Default::default(), focus: 1, cursor: 0 },
            sort_popup: SortState { order: SortDirection::Descending, available: vec![], applied: vec![], focus: 0, sel_available: 0, sel_applied: 0 },
            help_tab: 0,
            msg: None,
            export_state: ExportState { path: Input::new(""), message: String::new() },
            tags_popup: TagsState { items: vec![], selected: Default::default(), cursor: 0 },
            tag_colors, tag_index,
            quit: false,
            backend, backend_type,
            content_scroll: 0,
            cursor_pos: None,
        };
        app.sort_popup.applied = sorter.criteria.clone();
        app.sort_popup.order = sorter.order;
        app.sort_popup.available = all_criteria_except(&sorter.criteria);
        app.apply_filter();
        app
    }

    fn tag_color(&self, tag: &str) -> Option<(Option<Color>, Option<Color>)> {
        if !self.settings.colored_tags { return None; }
        self.tag_index.get(tag).and_then(|i| self.tag_colors.get(*i).copied())
    }

    fn visible_entries(&self) -> Vec<usize> { self.filtered.clone() }

    fn apply_filter(&mut self) {
        let list: Vec<usize> = (0..self.entries.len()).collect();
        if !self.filter_active {
            self.filtered = list;
        } else {
            self.filtered = list.into_iter().filter(|i| self.matches(&self.entries[*i])).collect();
        }
        if self.filtered.is_empty() { self.selected = 0; }
        else if self.selected >= self.filtered.len() { self.selected = self.filtered.len() - 1; }
    }

    fn matches(&self, e: &Entry) -> bool {
        let f = &self.filter;
        let mut checks: Vec<bool> = vec![];
        if !f.title.is_empty() {
            checks.push(e.title.to_lowercase().contains(&f.title.as_str().to_lowercase()));
        }
        if !f.content.is_empty() {
            checks.push(e.content.to_lowercase().contains(&f.content.as_str().to_lowercase()));
        }
        if !f.priority.is_empty() {
            match f.priority.as_str().parse::<u32>() {
                Ok(p) => checks.push(e.priority == Some(p)),
                Err(_) => checks.push(false),
            }
        }
        if !f.tags.is_empty() {
            match f.logic {
                MatchingLogic::All => checks.push(f.tags.iter().all(|t| e.tags.contains(t))),
                MatchingLogic::Any => checks.push(f.tags.iter().any(|t| e.tags.contains(t))),
            }
        }
        if checks.is_empty() { return true; }
        match f.logic { MatchingLogic::All => checks.iter().all(|b| *b), MatchingLogic::Any => checks.iter().any(|b| *b) }
    }

    fn sorted(&self) -> Vec<usize> {
        let mut idx: Vec<usize> = self.filtered.clone();
        let dir = self.sorter.order;
        for c in self.sorter.criteria.iter().rev() {
            match c {
                SortCriteria::Date => idx.sort_by(|a, b| self.entries[*a].date.cmp(&self.entries[*b].date)),
                SortCriteria::Priority => idx.sort_by(|a, b| match (self.entries[*a].priority, self.entries[*b].priority) {
                    (Some(x), Some(y)) => x.cmp(&y),
                    (None, Some(_)) => std::cmp::Ordering::Greater,
                    (Some(_), None) => std::cmp::Ordering::Less,
                    (None, None) => std::cmp::Ordering::Equal,
                }),
                SortCriteria::Title => idx.sort_by(|a, b| self.entries[*a].title.cmp(&self.entries[*b].title)),
            }
            if dir == SortDirection::Descending { idx.reverse(); }
        }
        idx
    }

    fn current(&self) -> Option<&Entry> {
        let list = self.sorted();
        list.get(self.selected).map(|i| &self.entries[*i])
    }
    fn current_id(&self) -> Option<u32> { self.current().map(|e| e.id) }

    fn save(&self) -> anyhow::Result<()> {
        self.backend.save(&self.entries)
    }
}

fn all_criteria_except(applied: &[SortCriteria]) -> Vec<SortCriteria> {
    let all = [SortCriteria::Date, SortCriteria::Priority, SortCriteria::Title];
    all.into_iter().filter(|c| !applied.contains(c)).collect()
}

fn build_tag_colors(entries: &[Entry]) -> (Vec<(Option<Color>, Option<Color>)>, std::collections::HashMap<String, usize>) {
    let palette: [(Option<Color>, Option<Color>); 9] = [
        (Some(Color::Black), Some(Color::LightCyan)),
        (Some(Color::Black), Some(Color::LightRed)),
        (Some(Color::Black), Some(Color::LightGreen)),
        (None, Some(Color::DarkGray)),
        (Some(Color::Black), Some(Color::LightYellow)),
        (None, Some(Color::Red)),
        (Some(Color::Yellow), Some(Color::Blue)),
        (Some(Color::Red), Some(Color::Cyan)),
        (Some(Color::Black), Some(Color::LightMagenta)),
    ];
    let mut map = std::collections::HashMap::new();
    let mut idx = 0usize;
    for e in entries {
        for t in &e.tags {
            if !map.contains_key(t) { map.insert(t.clone(), idx); idx += 1; }
        }
    }
    (palette.to_vec(), map)
}
