use ratatui::prelude::*;
use ratatui::layout::Constraint;
// (H, y) for popups with a fixed height
const EXPORT: [(u16,u16); 18] = [(19,4),(20,4),(21,5),(22,6),(24,6),(26,8),(28,8),(30,10),(32,11),(34,11),(36,12),(40,14),(44,16),(48,18),(52,20),(56,22),(60,24),(70,29)];
fn test(name: &str, obs: &[(u16,u16)], ph: u16){
    let area = |h: u16| Rect::new(0,0,120,h);
    for mode in 0..6 {
        let mut bad = vec![];
        for (h,want) in obs {
            let py = match mode { 0 => ph*100/h, 1 => (ph*100 + h/2)/h, 2 => (ph*100 + h - 1)/h, 3 => ph*100/h, 4 => (ph*100*2+h)/(2*h), _ => ph*100/h };
            let m = match mode { 0|1|2 => (100-py)/2, 3|4 => (100-py+1)/2, _ => (99-py)/2 };
