            if y != *want { bad.push((h,y)); }
        }
        println!("{} mode{} bad={}/{} bads={:?}", name, mode, bad.len(), obs.len(), bad);
    }
    // simple formulas
    for (i,(f,label)) in [(0usize,"floor((H-ph)/2)"),(1,"ceil"),(2,"round-half-up")].iter().enumerate() {
        let _ = f;
        let mut bad = vec![];
        for (h,want) in obs {
            let d = (*h as i32 - ph as i32);
            let y = match i { 0 => d/2, 1 => (d+1)/2, _ => (d*2+1)/4 };
            if y != *want as i32 { bad.push((h,y)); }
        }
        println!("{} {} bad={}/{} bads={:?}", name, label, bad.len(), obs.len(), bad);
    }
}
fn main(){
    test("EXPORT(ph=11)", &EXPORT, 11);
}
