// ---------- text wrapping (mirrors ratatui's WordWrapper with trim=true) ----------
fn char_width(c: char) -> usize {
    let w = unicode_width(c);
    w
}
fn unicode_width(c: char) -> usize {
    // narrow approximation adequate for the app's texts; wide chars handled via table below
    let cp = c as u32;
    if cp == 0 { return 0; }
    if (0x1100..=0x115F).contains(&cp) || (0x2E80..=0xA4CF).contains(&cp) || (0xAC00..=0xD7A3).contains(&cp)
        || (0xF900..=0xFAFF).contains(&cp) || (0xFE30..=0xFE6F).contains(&cp) || (0xFF00..=0xFF60).contains(&cp)
        || (0xFFE0..=0xFFE6).contains(&cp) || (0x20000..=0x3FFFD).contains(&cp) { return 2; }
    if (0x0300..=0x036F).contains(&cp) { return 0; }
    1
}

fn wrap_line(chars: &[char], max: usize, trim: bool) -> Vec<String> {
    let mut wrapped: Vec<Vec<char>> = vec![];
    let mut pending_line: Vec<char> = vec![];
    let mut line_width = 0usize;
    let mut word_width = 0usize;
    let mut ws_width = 0usize;
    let mut non_ws_prev = false;
    let mut pending_word: Vec<char> = vec![];
    let mut pending_ws: Vec<char> = vec![];
    for &g in chars {
        let is_ws = g.is_whitespace();
        let w = char_width(g);
        if w > max { continue; }
        let word_found = non_ws_prev && is_ws;
        let trimmed_overflow = pending_line.is_empty() && trim && word_width + w > max;
        let ws_overflow = pending_line.is_empty() && trim && ws_width + w > max;
        let untrimmed_overflow = pending_line.is_empty() && !trim && word_width + ws_width + w > max;
        if word_found || trimmed_overflow || ws_overflow || untrimmed_overflow {
            if !pending_line.is_empty() || !trim {
                pending_line.extend(pending_ws.drain(..));
                line_width += ws_width;
            }
            pending_line.append(&mut pending_word);
            line_width += word_width;
            pending_ws.clear();
            ws_width = 0;
            word_width = 0;
        }
        let line_full = line_width >= max;
        let pending_word_overflow = w > 0 && line_width + ws_width + word_width >= max;
        if line_full || pending_word_overflow {
            let mut remaining = max.saturating_sub(line_width);
            wrapped.push(std::mem::take(&mut pending_line));
            line_width = 0;
            while let Some(&c) = pending_ws.first() {
                let cw = char_width(c);
                if cw > remaining { break; }
                ws_width -= cw;
                remaining -= cw;
                pending_ws.remove(0);
            }
            if is_ws && pending_ws.is_empty() { continue; }
        }
        if is_ws { ws_width += w; pending_ws.push(g); }
        else { word_width += w; pending_word.push(g); }
        non_ws_prev = !is_ws;
    }
    if pending_line.is_empty() && pending_word.is_empty() && !pending_ws.is_empty() && trim {
        wrapped.push(vec![]);
    }
    if !pending_line.is_empty() || !trim {
        pending_line.extend(pending_ws.drain(..));
    }
    pending_line.append(&mut pending_word);
    if !pending_line.is_empty() { wrapped.push(pending_line); }
    if wrapped.is_empty() { wrapped.push(vec![]); }
    wrapped.into_iter().map(|v| v.into_iter().collect()).collect()
}

pub fn wrap_count(text: &str, width: u16) -> usize {
    if width == 0 { return 0; }
    let mut total = 0;
    for l in text.split('\n') {
        let chars: Vec<char> = l.chars().collect();
        total += wrap_line(&chars, width as usize, true).len();
    }
    total.max(1)
}

fn offset_center(max: u16, w: u16) -> u16 { (max / 2).saturating_sub(w / 2) }

fn render_wrapped(f: &mut Frame, area: Rect, text: &str, alignment: Alignment2, style: Style) {
    if area.width == 0 || area.height == 0 { return; }
    let width = area.width as usize;
    let mut y = area.y;
    for l in text.split('\n') {
        let chars: Vec<char> = l.chars().collect();
        for wl in wrap_line(&chars, width, true) {
            if y >= area.bottom() { return; }
            let lw = wl.chars().map(char_width).sum::<usize>() as u16;
            let x = match alignment {
                Alignment2::Left => area.x,
                Alignment2::Center => area.x + offset_center(area.width, lw),
            };
            let s: String = wl.into_iter().collect();
            let line = Line::from(Span::styled(s, style));
            f.render_widget(line, Rect::new(x, y, area.width, 1));
            y += 1;
        }
    }
}

#[derive(Clone, Copy, PartialEq, Eq)]
enum Alignment2 { Left, Center }
EOF
echo ok

