const HINT_EXPORT: &str = "Enter: confirm | Esc or <Ctrl-c>: Cancel";
const HINT_TAGS: &str = "<Space>: Toggle Selected | Enter or <Ctrl-m>: Confirm | Esc, q or <Ctrl-c>: Cancel";
const FOOTER_NORMAL: &str = "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Open filter: 'f' | Open sort options: 'o' | Show help: '?'";
const FOOTER_FILTERED: &str = "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Reset filter: 'x' | Open sort options: 'o' | Show help: '?'";
const FOOTER_CONTENT: &str = "Exit: 'q' | Edit journal content: 'Enter','<Ctrl-m>' | Show help: '?'";
const FOOTER_EDIT: &str = "Back to Editor Normal Mode: 'Esc','<Ctrl-c>','<Ctrl-[>' |  Edit using Emacs motions";
const FOOTER_MULTI: &str = "Leave journals multi selection mode: 'q','v','Esc','<Ctrl-c>' | Show help: '?'";

const HELP_GLOBAL: &str = "Key                Command                      Description                                           \n\
q                  Exit                         Exit the program\n\
?                  Show help                    Show keybindings overview\n\
<Ctrl-l>, Tab      Cycle focus forward          Move focus to the next control\n\
<Ctrl-h>, BackTab  Cycle focus backward         Move focus to the previous control\n\
Down, j            Select next journal          Select next entry in the journals list\n\
Up, k              Select previous journal      Select previous entry in the journal list\n\
n                  Create new journal           Opens dialog to add a new journal entry\n\
e                  Edit current journal         Open entry dialog to edit current journal entry if any\n\
Delete, d, <Ctrl-d> Delete journal              Delete current journal entry if any\n\
Enter, <Ctrl-m>    Edit journal content         Start editing current journal entry content in editor\n\
Esc, <Ctrl-c>, <Ctrl-[> Back to Editor Normal Mode Exit editor special modes (insert, visual) and go back to normal mode\n\
s, <Ctrl-s>        Save                         Save changes on journal content\n\
<Ctrl-q>           Discard changes              Discard changes on journal content\n\
<Ctrl-r>           Reload all                   Reload all entries\n\
>                  Export journal content       Export current journal content\n\
<Ctrl-y>, y        Edit in external editor      Edit current journal content in external editor (The editor can be set in configurations file or via the environment variables VISUAL, EDITOR)";

fn app_footer(&self) -> &'static str {
    if self.multi_select { FOOTER_MULTI }
    else if self.editor_mode != EditorMode::Normal { FOOTER_EDIT }
    else if self.focus == Focus::Content { FOOTER_CONTENT }
    else if self.filter_active { FOOTER_FILTERED }
    else { FOOTER_NORMAL }
}

fn journals_title(&self) -> String {
    if self.multi_select { "Journals - Multi-Select".into() }
    else if self.filter_active { "Journals - Filtered".into() }
    else { "Journals".into() }
}

fn content_title(&self) -> String {
    let base = match self.editor_mode {
        EditorMode::Normal => "Content - NORMAL",
        EditorMode::Insert => "Content - EDIT",
        EditorMode::Visual => "Content - Visual",
    };
    let suffix = if self.editor_dirty { " *" } else { "" };
    format!("{}{}", base, suffix)
}

fn render(&mut self, f: &mut Frame) {
    let area = f.area();
    let footer = self.app_footer();
    let fl = wrap_count(footer, area.width) as u16;
    let main_h = area.height.saturating_sub(fl);
    let main = Rect::new(area.x, area.y, area.width, main_h);
    let footer_area = Rect::new(area.x, area.y + main_h, area.width, fl);
    let [journals, content] = Layout::horizontal([Constraint::Percentage(30), Constraint::Percentage(70)]).split(main);

    // ---- journals list ----
    let list_style = if self.multi_select { self.theme.journals_block_multi_select }
        else if self.focus == Focus::Journals { self.theme.journals_block_active }
        else { self.theme.journals_block_inactive };
    let title = self.journals_title();
    let count_text = if self.entries.is_empty() { String::new() } else {
        format!("{}/{}", self.selected + 1, self.sorted().len())
    };
    let mut b = Block::bordered().title(title).style(list_style);
    if !count_text.is_empty() {
        b = b.title(Line::from(count_text).right_aligned());
    }
    let inner = b.inner(journals);
    f.render_widget(b, journals);
    let list = self.sorted();
    if list.is_empty() {
        let ph_area = Rect::new(inner.x, inner.y + 1, inner.width, inner.height.saturating_sub(1));
        render_wrapped(f, ph_area, "Use 'n' to create new entry", Alignment2::Center, Style::default());
    } else {
        let items: Vec<ListItem> = list.iter().enumerate().map(|(pos, idx)| {
            let e = &self.entries[*idx];
            let title_style = if self.focus == Focus::Journals { self.theme.journals_title_active } else { self.theme.journals_title_inactive };
            let mut l1 = Line::from(Span::styled(e.title.clone(), title_style));
            let date_str = match self.settings.datum_visibility { DatumVisibility::Show => {
                match e.priority { Some(p) => format!("{} | Priority: {}", model::format_date_list(&e.date), p), None => model::format_date_list(&e.date) }
            }, DatumVisibility::Hide => String::new(), DatumVisibility::EmptyLine => String::new() };
            let l2 = if date_str.is_empty() { Line::from("") } else { Line::from(Span::styled(date_str, self.theme.journals_date_priority)) };
            let mut spans: Vec<Span> = vec![];
            if e.tags.is_empty() {
                spans.push(Span::raw(""));
            } else {
                for (i, t) in e.tags.iter().enumerate() {
                    if i > 0 { spans.push(Span::styled(" | ", self.theme.journals_tags_default)); }
                    let st = self.tag_color(t).map(|(fg, bg)| { let mut s = Style::default(); if let Some(f) = fg { s = s.fg(f); } if let Some(b) = bg { s = s.bg(b); } s })
                        .unwrap_or_else(|| { if self.settings.colored_tags { Style::default() } else { self.theme.journals_tags_default } });
                    spans.push(Span::styled(t.clone(), st));
                }
            }
            let _ = &mut l1;
            ListItem::new(vec![l1, l2, Line::from(spans)]).style(Style::reset())
        }).collect();
        let hl = if self.focus == Focus::Journals { self.theme.journals_highlight_active } else { self.theme.journals_highlight_inactive };
        let mut st = ListState::default().with_selected(Some(self.selected));
        let w = List::new(items).highlight_symbol("> ").highlight_style(hl);
        f.render_stateful_widget(w, inner, &mut st);
    }

    // ---- content pane ----
    self.render_content(f, content);

    // ---- footer ----
    render_wrapped(f, footer_area, footer, Alignment2::Left, Style::default());

    // ---- popups ----
    self.render_popup(f, area);
}
EOF
echo ok"}

