        let cx = inner.x + 3;
        let cw = inner.width.saturating_sub(6);
        let block_style = |active: bool, invalid: bool| {
            if invalid { self.theme.general_input_block_invalid } else if active { self.theme.general_input_block_active } else { Style::default() }
        };
        let mut y = inner.y + 1;
        let fields = [("Title", self.dlg.title.as_str(), self.dlg.focus == 0, !self.dlg.valid_title),
                      ("Date", self.dlg.date.as_str(), self.dlg.focus == 1, !self.dlg.valid_date),
                      ("Priority", self.dlg.priority.as_str(), self.dlg.focus == 2, !self.dlg.valid_priority),
                      ("Tags", self.dlg.tags.as_str(), self.dlg.focus == 3, !self.dlg.valid_tags)];
        for (i, (name, val, active, invalid)) in fields.iter().enumerate() {
            let style = block_style(*active, *invalid);
            let blk = Block::bordered().title(*name).style(style);
            f.render_widget(blk, Rect::new(cx, y, cw, 3));
            f.render_widget(Line::from(Span::styled(val.to_string(), Style::default())), Rect::new(cx + 1, y + 1, cw - 2, 1));
            if *active {
