        let active = self.sort_popup.focus == 0;
        f.render_widget(Block::bordered().title("Sort Order").style(if active { self.theme.general_input_block_active } else { Style::default() }), Rect::new(cx, y, cw, 3));
        render_wrapped(f, Rect::new(cx + 1, y + 1, cw - 2, 1), order_text, Alignment2::Center, Style::default());
        y += 3;
