        f.render_widget(tb, ta);
        let ca = Rect::new(inner.x + 1, inner.y + 3, inner.width.saturating_sub(2), inner.height.saturating_sub(3));
        let title = match self.help_tab { 0 => "Global Keybindings", 1 => "Editor Keybindings", _ => "Multi-Select Mode Keybindings" };
        let cb = Block::bordered().title(title);
