            _ => "Key                Command                      Description\n\n?                  Show help                    Show keybindings overview\nDown, j            Select next journal          Select next entry in the journals list\nUp, k              Select previous journal      Select previous entry in the journal list\nq, v, Esc, <Ctrl-c> Leave journals multi selection mode Leave multi selection mode for journals and return to normal mode\n<Space>, Enter, <Ctrl-m> Toggle selected            Toggle if the current journal is selected in multi selection mode\na                  Select all journals          Select all journals in multi selection mode\nx                  Clear selection              Clear journals selection in multi selection mode\ni                  Invert selection             Invert journals selection in multi selection mode\nd, Delete          Delete selection             Delete selected journals in multi selection mode\n>                  Export selection             Export selected journals to a transfer JSON file, which can be imported to other back-end files",
        };
        let ia = Rect::new(ca.x + 1, ca.y + 1, ca.width.saturating_sub(2), ca.height.saturating_sub(2));
        render_wrapped(f, ia, body, Alignment2::Left, Style::default());
    }

    fn render_export(&mut self, f: &mut Frame, popup: Rect, hint_lines: u16) {
        let (title, msg) = match self.popup {
            WhichPopup::ExportJournal => ("Export journal content", format!("Journal: {}", self.current().map(|e| e.title.clone()).unwrap_or_default())),
            WhichPopup::ExportJournals => ("Export journals", format!("Export the selected {} journals", self.selected_set.len())),
            _ => ("Export journals", String::new()),
        };
        let b = Block::bordered().title(title).style(Style::default());
        let inner = b.inner(popup);
        f.render_widget(b, popup);
        let cx = inner.x + 3;
        let cw = inner.width.saturating_sub(6);
        let mut y = inner.y + 1;
        if !msg.is_empty() { render_wrapped(f, Rect::new(cx, y, cw, 1), &msg, Alignment2::Left, Style::default()); }
        y += 2;
        let active = true;
        f.render_widget(Block::bordered().title("Path").style(if active { self.theme.general_input_block_active } else { Style::default() }), Rect::new(cx, y, cw, 3));
        f.render_widget(Line::from(self.export_state.path.as_str()), Rect::new(cx + 1, y + 1, cw - 2, 1));
        f.set_cursor_position((cx + 1 + self.export_state.path.cursor as u16, y + 1));
        y += 4;
        render_wrapped(f, Rect::new(cx, y, cw, hint_lines), HINT_EXPORT, Alignment2::Center, Style::default());
    }

    fn render_msg(&mut self, f: &mut Frame, popup: Rect, msg: &MsgBox, lines: u16) {
        let color = match msg.kind { MsgKind::Error => self.theme.msg_error, MsgKind::Warning => self.theme.msg_warning, MsgKind::Info => self.theme.msg_info, MsgKind::Question => self.theme.msg_question };
        let title = match msg.kind { MsgKind::Error => "Error", MsgKind::Warning => "Warning", MsgKind::Info => "Info", MsgKind::Question => "" };
        let mut b = Block::bordered().style(Style::default().fg(color));
        if !title.is_empty() { b = b.title(title); }
        let inner = b.inner(popup);
        f.render_widget(b, popup);
        let mut y = inner.y;
        render_wrapped(f, Rect::new(inner.x, y, inner.width, 1), "", Alignment2::Left, Style::default());
        y += 1;
        render_wrapped(f, Rect::new(inner.x, y, inner.width, lines), &msg.message, Alignment2::Center, Style::default());
        y += lines;
        y += 2;
        let answer = match msg.kind { MsgKind::Question => "(Y)es , (N)o", _ => "(O)k" };
        render_wrapped(f, Rect::new(inner.x, y, inner.width, 1), answer, Alignment2::Center, Style::default());
    }

    fn render_tags(&mut self, f: &mut Frame, popup: Rect) {
        let inner = Rect::new(popup.x + 1, popup.y + 1, popup.width.saturating_sub(2), popup.height.saturating_sub(2));
        let w = inner.width * 7 / 10;
        let x = inner.x + (inner.width.saturating_sub(w)) / 2;
        let rect = Rect::new(x, inner.y, w, inner.height);
        let b = Block::bordered().title("Tags").border_type(BorderType::Rounded).style(Style::default());
        let ta = b.inner(rect);
        f.render_widget(b, rect);
        let mut y = ta.y;
        for (i, t) in self.tags_popup.items.iter().enumerate() {
            if y >= ta.bottom().saturating_sub(3) { break; }
            let marker = if i == self.tags_popup.cursor { ">> " } else { "   " };
            f.render_widget(Line::from(format!("{}{}", marker, t)), Rect::new(ta.x, y, ta.width, 1));
            y += 1;
        }
        let hy = rect.bottom().saturating_sub(4);
        render_wrapped(f, Rect::new(ta.x, hy, ta.width, 2), HINT_TAGS, Alignment2::Center, Style::default());
    }
}
