    fn render_msg(&mut self, f: &mut Frame, popup: Rect, msg: &MsgBox, lines: u16) {
        let color = match msg.kind { MsgKind::Error => self.theme.msg_error, MsgKind::Warning => self.theme.msg_warning, MsgKind::Info => self.theme.msg_info, MsgKind::Question => self.theme.msg_question };
        let title = match msg.kind { MsgKind::Error => "Error", MsgKind::Warning => "Warning", MsgKind::Info => "Info", MsgKind::Question => "" };
        let mut b = Block::bordered().style(Style::default().fg(color));
        if !title.is_empty() { b = b.title(title); }
        let inner = b.inner(popup);
        f.render_widget(b, popup);
        let mut y = inner.y;
        render_wrapped(f, Rect::new(inner.x, y, inner.width, 1), "", Alignment2::Left, Style::default());
        y += 1;
        render_wrapped(f, Rect::new(inner.x, y, inner.width, lines), &msg.message, Alignment2::Center, Style::default());
        y += lines;
        y += 2;
        let answer = match msg.kind { MsgKind::Question => "(Y)es , (N)o", _ => "(O)k" };
        render_wrapped(f, Rect::new(inner.x, y, inner.width, 1), answer, Alignment2::Center, Style::default());
    }

    fn render_tags(&mut self, f: &mut Frame, popup: Rect) {
        let inner = Rect::new(popup.x + 1, popup.y + 1, popup.width.saturating_sub(2), popup.height.saturating_sub(2));
        let w = inner.width * 7 / 10;
        let x = inner.x + (inner.width.saturating_sub(w)) / 2;
        let rect = Rect::new(x, inner.y, w, inner.height);
        let b = Block::bordered().title("Tags").border_type(BorderType::Rounded).style(Style::default());
