pub fn run(settings: &Settings, backend_type: BackendType, config_dir: &std::path::Path) -> anyhow::Result<()> {
    let theme = Theme::load(config_dir).map_err(|e| anyhow::anyhow!("Error while retrieving app styles").context(e))?;
    let backend = crate::backend::make_backend(backend_type, settings);
    let entries = backend.load()?;
    let sorter = load_state(settings).unwrap_or_else(|_| Sorter::default_sorter());
    run_app(settings.clone(), theme, entries, backend, backend_type, sorter)
}

pub fn run_with_msg<F: FnOnce(&[Entry]) -> Vec<Entry> + 'static>(
    settings: &Settings, backend_type: BackendType, _pre: Vec<Entry>, msg: &str, action: F) {
    let theme = Theme::load(&Settings::config_dir()).unwrap_or_else(|_| crate::theme::Theme::load(Settings::config_dir()).unwrap());
    let backend = crate::backend::make_backend(backend_type, settings);
    let entries = match backend.load() { Ok(e) => e, Err(e) => { eprint!("Error: {}", format_error_chain(&*e)); std::process::exit(1); } };
    let sorter = load_state(settings).unwrap_or_else(|_| Sorter::default_sorter());
    let _ = crate::ui::run_with_msg_impl(settings.clone(), theme, entries, backend, backend_type, sorter, msg, action);
}

pub fn load_state(settings: &Settings) -> anyhow::Result<Sorter> {
    let p = settings.app_state_dir.join("state.json");
    if !p.exists() { return Ok(Sorter::default_sorter()); }
    let s = std::fs::read_to_string(&p)?;
    #[derive(serde::Deserialize)]
    struct St { sorter: Sorter, #[allow(dead_code)] full_screen: bool }
    let st: St = serde_json::from_str(&s)?;
    Ok(st.sorter)
}

pub fn save_state(settings: &Settings, sorter: &Sorter) -> anyhow::Result<()> {
    std::fs::create_dir_all(&settings.app_state_dir)?;
    let body = format!("{{\n  \"sorter\": {{\n    \"criteria\": [\n{}\n    ],\n    \"order\": \"{}\"\n  }},\n  \"full_screen\": false\n}}",
        sorter.criteria.iter().map(|c| format!("      \"{:?}\"", c)).collect::<Vec<_>>().join(",\n"),
        match sorter.order { SortDirection::Descending => "Descending", _ => "Ascending" });
    std::fs::write(settings.app_state_dir.join("state.json"), body)?;
    Ok(())
}

fn run_app(settings: Settings, theme: Theme, entries: Vec<Entry>, backend: Box<dyn crate::backend::Backend>, backend_type: BackendType, sorter: Sorter) -> anyhow::Result<()> {
    let mut app = App::new(settings, theme, entries, backend, backend_type, sorter);
    let mut stdout = std::io::stdout();
    crossterm::terminal::enable_raw_mode()?;
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen, crossterm::cursor::Hide)?;
    let backend_t = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend_t)?;
    terminal.draw(|f| app.render(f))?;
    loop {
        if app.quit { break; }
        if crossterm::event::poll(std::time::Duration::from_millis(200))? {
            if let crossterm::event::Event::Key(key) = crossterm::event::read()? {
                if key.kind == crossterm::event::KeyEventKind::Press { app.handle_key(key); }
            }
        }
        terminal.draw(|f| app.render(f))?;
    }
    crate::ui::save_state(&app.settings, &app.sorter)?;
    let _ = app.backend.save(&app.entries);
    crossterm::execute!(std::io::stdout(), crossterm::cursor::Show, crossterm::terminal::LeaveAlternateScreen)?;
    crossterm::terminal::disable_raw_mode()?;
    Ok(())
}

pub fn run_with_msg_impl<F: FnOnce(&[Entry]) -> Vec<Entry>>(
    settings: Settings, theme: Theme, entries: Vec<Entry>, backend: Box<dyn crate::backend::Backend>,
    backend_type: BackendType, sorter: Sorter, msg: &str, action: F) -> anyhow::Result<()> {
    let _ = (&theme, &backend_type);
    let mut stdout = std::io::stdout();
    crossterm::terminal::enable_raw_mode()?;
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen, crossterm::cursor::Hide)?;
    let backend_t = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend_t)?;
    let new_entries = action(&entries);
    let msgbox = MsgBox { kind: MsgKind::Info, message: msg.to_string() };
    let mut app = App::new(settings, theme, new_entries, backend, backend_type, sorter);
    app.msg = Some(msgbox);
    app.popup = WhichPopup::Msg;
    terminal.draw(|f| app.render(f))?;
    // wait for a key to dismiss
    loop {
        if crossterm::event::poll(std::time::Duration::from_millis(5000))? {
            if let crossterm::event::Event::Key(key) = crossterm::event::read()? {
                if key.kind == crossterm::event::KeyEventKind::Press { break; }
            }
        } else { break; }
    }
    app.msg = None;
    app.popup = WhichPopup::None;
    loop {
        if app.quit { break; }
        if crossterm::event::poll(std::time::Duration::from_millis(200))? {
            if let crossterm::event::Event::Key(key) = crossterm::event::read()? {
                if key.kind == crossterm::event::KeyEventKind::Press { app.handle_key(key); }
            }
        }
