    crossterm::execute!(std::io::stdout(), crossterm::cursor::Show, crossterm::terminal::LeaveAlternateScreen)?;
    crossterm::terminal::disable_raw_mode()?;
    Ok(())
}

pub fn run_with_msg_impl<F: FnOnce(&[Entry]) -> Vec<Entry>>(
    settings: Settings, theme: Theme, entries: Vec<Entry>, backend: Box<dyn crate::backend::Backend>,
    backend_type: BackendType, sorter: Sorter, msg: &str, action: F) -> anyhow::Result<()> {
    let _ = (&theme, &backend_type);
    let mut stdout = std::io::stdout();
    crossterm::terminal::enable_raw_mode()?;
    crossterm::execute!(stdout, crossterm::terminal::EnterAlternateScreen, crossterm::cursor::Hide)?;
    let backend_t = ratatui::backend::CrosstermBackend::new(stdout);
    let mut terminal = ratatui::Terminal::new(backend_t)?;
    let new_entries = action(&entries);
    let msgbox = MsgBox { kind: MsgKind::Info, message: msg.to_string() };
    let mut app = App::new(settings, theme, new_entries, backend, backend_type, sorter);
    app.msg = Some(msgbox);
    app.popup = WhichPopup::Msg;
    terminal.draw(|f| app.render(f))?;
    // wait for a key to dismiss
    loop {
        if crossterm::event::poll(std::time::Duration::from_millis(5000))? {
            if let crossterm::event::Event::Key(key) = crossterm::event::read()? {
                if key.kind == crossterm::event::KeyEventKind::Press { break; }
            }
        } else { break; }
    }
    app.msg = None;
    app.popup = WhichPopup::None;
    loop {
        if app.quit { break; }
        if crossterm::event::poll(std::time::Duration::from_millis(200))? {
            if let crossterm::event::Event::Key(key) = crossterm::event::read()? {
                if key.kind == crossterm::event::KeyEventKind::Press { app.handle_key(key); }
            }
        }
        terminal.draw(|f| app.render(f))?;
    }
    crate::ui::save_state(&app.settings, &app.sorter)?;
    let _ = app.backend.save(&app.entries);
    crossterm::execute!(std::io::stdout(), crossterm::cursor::Show, crossterm::terminal::LeaveAlternateScreen)?;
    crossterm::terminal::disable_raw_mode()?;
    Ok(())
}
