            K::Up | K::Char('k') => { if self.sort_popup.focus == 1 { if self.sort_popup.sel_available > 0 { self.sort_popup.sel_available -= 1; } } else if self.sort_popup.sel_applied > 0 { self.sort_popup.sel_applied -= 1; } }
